:root {
  --color-bg: #1e1e2f;
  --color-card: #2a2a40;
  --color-primary: #6c5ce7;
  --color-primary-hover: #5a4bd1;
  --color-text: #f0f0f5;
  --color-muted: #a0a0b8;
  --color-border: #3d3d5c;
  --color-danger: #e74c3c;
  --font-base: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: var(--font-base);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 24px 16px;
}

.card {
  background: var(--color-card);
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 640px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  text-align: center;
  letter-spacing: 0.5px;
}

h2 {
  font-size: 1.125rem;
  margin-bottom: 16px;
  color: var(--color-muted);
  font-weight: 600;
}

section {
  margin-bottom: 28px;
}

.form-row {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

label {
  font-size: 0.9375rem;
  color: var(--color-muted);
}

input {
  font-size: 1rem;
  padding: 10px 12px;
  border-radius: 8px;
  border: 2px solid var(--color-border);
  background: var(--color-bg);
  color: var(--color-text);
  outline: none;
  transition: border-color 0.2s;
}

input:focus {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(108, 92, 231, 0.3);
}

button {
  font-size: 1rem;
  padding: 12px 20px;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  font-weight: 600;
  transition: background 0.2s, transform 0.1s;
}

.btn-primary {
  background: var(--color-primary);
  color: #fff;
  width: 100%;
}

.btn-primary:hover {
  background: var(--color-primary-hover);
}

.btn-primary:active {
  transform: scale(0.98);
}

.btn-primary:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.item-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.item {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  background: var(--color-bg);
  padding: 12px 14px;
  border-radius: 8px;
  border: 1px solid var(--color-border);
  gap: 8px;
}

.item-info {
  flex: 1 1 180px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.item-desc {
  font-weight: 600;
}

.item-meta {
  font-size: 0.875rem;
  color: var(--color-muted);
}

.item-total {
  font-weight: 700;
  color: var(--color-primary);
  min-width: 80px;
  text-align: right;
}

.remove-btn {
  background: transparent;
  color: var(--color-danger);
  border: 2px solid var(--color-danger);
  padding: 6px 12px;
  font-size: 0.875rem;
  border-radius: 6px;
}

.remove-btn:hover {
  background: var(--color-danger);
  color: #fff;
}

.remove-btn:active {
  transform: scale(0.95);
}

.remove-btn:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.empty-msg {
  color: var(--color-muted);
  font-style: italic;
  text-align: center;
  padding: 16px 0;
}

.totals {
  border-top: 2px solid var(--color-border);
  padding-top: 20px;
}

.total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  font-size: 1rem;
}

.tax-row label {
  font-size: 1rem;
  color: var(--color-text);
}

.tax-row input {
  width: 100px;
  text-align: right;
}

.grand-total {
  font-size: 1.25rem;
  font-weight: 700;
  border-top: 2px solid var(--color-border);
  margin-top: 8px;
  padding-top: 16px;
  color: var(--color-primary);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .item {
    flex-direction: column;
    align-items: stretch;
  }
  .item-total {
    text-align: left;
  }
}

const descInput = document.getElementById('desc-input');
const qtyInput = document.getElementById('qty-input');
const priceInput = document.getElementById('price-input');
const addBtn = document.getElementById('add-btn');
const itemList = document.getElementById('item-list');
const emptyMsg = document.getElementById('empty-msg');
const subtotalEl = document.getElementById('subtotal');
const taxRateInput = document.getElementById('tax-rate');
const taxAmountEl = document.getElementById('tax-amount');
const grandTotalEl = document.getElementById('grand-total');

let items = [];

function formatCurrency(n) {
  return '$' + n.toFixed(2);
}

function calculateSubtotal() {
  return items.reduce((sum, item) => sum + item.qty * item.price, 0);
}

function updateTotals() {
  const subtotal = calculateSubtotal();
  const taxRate = parseFloat(taxRateInput.value) || 0;
  const tax = subtotal * (taxRate / 100);
  const grandTotal = subtotal + tax;

  subtotalEl.textContent = formatCurrency(subtotal);
  taxAmountEl.textContent = formatCurrency(tax);
  grandTotalEl.textContent = formatCurrency(grandTotal);
}

function renderItems() {
  itemList.innerHTML = '';
  if (items.length === 0) {
    emptyMsg.hidden = false;
    return;
  }
  emptyMsg.hidden = true;

  items.forEach((item, index) => {
    const li = document.createElement('li');
    li.className = 'item';

    const info = document.createElement('div');
    info.className = 'item-info';

    const desc = document.createElement('span');
    desc.className = 'item-desc';
    desc.textContent = item.desc || 'Unnamed item';

    const meta = document.createElement('span');
    meta.className = 'item-meta';
    meta.textContent = `${item.qty} × ${formatCurrency(item.price)}`;

    info.appendChild(desc);
    info.appendChild(meta);

    const total = document.createElement('span');
    total.className = 'item-total';
    total.textContent = formatCurrency(item.qty * item.price);

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'remove-btn';
    removeBtn.textContent = 'Remove';
    removeBtn.setAttribute('aria-label', `Remove ${item.desc || 'item'}`);
    removeBtn.addEventListener('click', () => {
      items.splice(index, 1);
      renderItems();
      updateTotals();
    });

    li.appendChild(info);
    li.appendChild(total);
    li.appendChild(removeBtn);
    itemList.appendChild(li);
  });
}

function addItem() {
  const desc = descInput.value.trim();
  const qty = parseFloat(qtyInput.value);
  const price = parseFloat(priceInput.value);

  if (!desc) {
    descInput.focus();
    return;
  }
  if (isNaN(qty) || qty <= 0) {
    qtyInput.focus();
    return;
  }
  if (isNaN(price) || price < 0) {
    priceInput.focus();
    return;
  }

  items.push({ desc, qty, price });
  descInput.value = '';
  qtyInput.value = '1';
  priceInput.value = '0.00';
  descInput.focus();

  renderItems();
  updateTotals();
}

addBtn.addEventListener('click', addItem);

descInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addItem();
});
qtyInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addItem();
});
priceInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter') addItem();
});

taxRateInput.addEventListener('input', updateTotals);

renderItems();
updateTotals();
